mapper.select:
SELECT 
  FROM act10_repr_account a
 WHERE a.act10_company_id = #{companyId}
   AND a.act10_attribute_cd LIKE #{attributeCode}
   AND UPPER(a.act10_repr_account_cd || a.act10_repr_account_nm) LIKE UPPER(#{searchText})
 ORDER BY a.act10_repr_account_cd

SELECT 
  FROM act10_repr_account a
 WHERE a.act10_repr_account_id = #{reprAccountId}

mapper.update:
UPDATE act10_repr_account
   SET act10_repr_account_cd     = #{req.reprAccountCode},
       act10_repr_account_nm     = #{req.reprAccountName},
       act10_attribute_cd        = #{req.attributeCode},
       act10_tgt_repr_account_cd = #{req.tgtReprAccountCode},
       act10_note                = #{req.note}
 WHERE act10_repr_account_id = #{req.reprAccountId}
   AND act10_company_id      = #{companyId}

mapper.delete:
DELETE FROM act10_repr_account
 WHERE act10_company_id = #{companyId}
   AND act10_repr_account_id IN
#{id}

DELETE FROM act10_repr_account
 WHERE act10_company_id      = #{companyId}
   AND act10_repr_account_cd = #{reprAccountCode}
